        >
          <FlaskConical className="size-3" /> {label}
        </span>
      </TooltipTrigger>
      <TooltipContent>
        Illustrative sample — not wired to a live backend yet. Real data comes from the caller-memory
        store and the LiveKit voice session.
      </TooltipContent>
    </Tooltip>
  );
}

